import React from "react";

export default function Slide12QnA({ onNext, onPrev }) {
  return (
    <div className="slide-content bg-gradient-to-r from-[#f5f5f5] to-[#e0e0e0] rounded-2xl p-8 md:p-12 shadow-xl">
      <h2 className="slide-title mb-6 text-gray-800">Tanya Jawab</h2>
      <div className="text-lg text-gray-700 mb-8">Silakan bertanya, tidak ada pertanyaan bodoh. Satu klik bisa fatal.</div>
      <div className="flex gap-4 justify-center">
        <button onClick={onPrev} className="bg-gray-200 text-gray-700 px-4 py-2 rounded-lg font-bold hover:bg-gray-300 transition">Back</button>
        <button onClick={onNext} className="bg-gray-700 text-white px-6 py-2 rounded-lg font-bold text-lg shadow hover:bg-gray-800 transition">Next</button>
      </div>
    </div>
  );
}
